def add_task(task_list):
    """Add a task to the task list."""
    task_list.append(input("Add task: "))


def remove_task(task_list):
    """Remove a task from the task list."""
    task_list.pop(int(input("Remove task: ")) - 1)


def check_task_list(task_list):
    """Output the current task list."""
    print("\nCurrent task list:")
    for i, task in enumerate(task_list, start=1):
        print(f"{i}. {task}")


def main():
    task_list = []

    while True:
        command = input("\nEnter 'add' to add a task, 'remove' to remove a task, or 'check' to check the task list: ").lower()

        if command == 'add':
            add_task(task_list)
        elif command == 'remove':
            remove_task(task_list)
        elif command == 'check':
            check_task_list(task_list)
        else:
            print("Invalid command. Please try again.")

        continue_input = input("Do you want to continue? (yes/no): ").lower()
        if continue_input != 'yes':
            break


if __name__ == "__main__":
    main()
```

This program will run in an infinite loop, waiting for user input. When the user enters a valid command (e.g., 'add', 'remove', or 'check'), the corresponding function will be called to update the task list. The program will continue to run until the user enters 'no' when prompted if they want to continue.
